    'ປະຫວັດຈັດກຸ່ມຕາມງວດຮັບເຂົ້າ. ຫຼາຍລາຍການໃຫ້ກົດລູກສອນ (▶) ເພື່ອຂະຫຍາຍ. ລາຍການສາຂາຕົນເອງ ຖ້າຄີຜິດ ແກ້ດ້ວຍໄອຄອນປາກກາ ຫຼື ລຶບໄດ້.',
