  bankInvoiceCheckTitle: 'ກວດໃບແຈ້ງເງິນ',
  bankInvoiceLinkPrompt: 'ເຊື່ອມລາຍການນີ້ກັບບີລສັ່ງຊື້ບໍ? ເມື່ອເຊື່ອມ ສະຖານະໃບແຈ້ງເງິນຈະຊິງກັນ',
