  bankNoPOForVendor: 'ບໍ່ມີບີລສັ່ງຊື້ຂອງຜູ້ຂາຍນີ້ ເຊັກເທົ່ານັ້ນ',
  bankManualTitle: 'ຄູ່ມືທະນາຄານ',
  bankManualDesc: 'ຈາກອັບໂຫລດ CSV ທະນາຄານ → ຈັບຄູ່ປະເພດ/ບັນຊີອັດຕະໂນມັດ → ເຊື່ອມໂຍງລູກໜີ້/ເຈົ້າໜີ້ ຄູ່ມືວິທີການເຕັມ',
